{"content":"import { useEffect, useRef, useState } from 'react'
import styles from './MagicBackground.module.css'

const PARTICLE_COUNT = 50
const SPARKLE_COUNT = 30

export const MagicBackground = ({ 
  intensity = 'medium', 
  color = 'gold',
  className = '',
  children 
}) => {
  const [particles, setParticles] = useState([])
  const [sparkles, setSparkles] = useState([])
  const containerRef = useRef(null)
  const animationRef = useRef(null)

  useEffect(() => {
    if (typeof window === 'undefined') return

    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    if (prefersReducedMotion) return

    // Generate initial particles
    const newParticles = Array.from({ length: PARTICLE_COUNT }, (_, i) => ({
      id: `particle-${i}`,
      x: Math.random() * 100,
      y: Math.random() * 100,
      size: Math.random() * 3 + 1,
      opacity: Math.random() * 0.5 + 0.1,
      speedX: (Math.random() - 0.5) * 0.3,
      speedY: -(Math.random() * 0.5 + 0.2),
      delay: Math.random() * 5,
      hue: color === 'gold' ? 45 + Math.random() * 20 : 200 + Math.random() * 40
    }))

    const newSparkles = Array.from({ length: SPARKLE_COUNT }, (_, i) => ({
      id: `sparkle-${i}`,
      x: Math.random() * 100,
      y: Math.random() * 100,
      size: Math.random() * 4 + 2,
      opacity: 0,
      phase: Math.random() * Math.PI * 2,
      duration: 2 + Math.random() * 3,
      delay: Math.random() * 4
    }))

    setParticles(newParticles)
    setSparkles(newSparkles)

    // Animation loop
    let lastTime = 0
    const animate = (currentTime) => {
      const deltaTime = (currentTime - lastTime) / 1000
      lastTime = currentTime

      setParticles(prev => prev.map(p => {
        let newY = p.y + p.speedY * deltaTime * 60
        let newX = p.x + p.speedX * deltaTime * 60

        if (newY < -5) {
          newY = 105
          newX = Math.random() * 100
        }
        if (newX < -5) newX = 105
        if (newX > 105) newX = -5

        return { ...p, x: newX, y: newY }
      }))

      setSparkles(prev => prev.map(s => {
        const elapsed = (currentTime / 1000 - s.delay) % s.duration
        const progress = elapsed / s.duration
        const newOpacity = progress < 0.1 ? progress * 10 : 
                          progress > 0.9 ? (1 - progress) * 10 : 1

        return { 
          ...s, 
          opacity: Math.max(0, Math.min(1, newOpacity)),
          phase: s.phase + deltaTime * 2
        }
      }))

      animationRef.current = requestAnimationFrame(animate)
    }

    animationRef.current = requestAnimationFrame(animate)

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current)
      }
    }
  }, [color, intensity])

  const intensityClass = {
    low: styles.low,
    medium: styles.medium,
    high: styles.high
  }[intensity] || styles.medium

  return (
    <div 
      ref={containerRef}
      className={`${styles.container} ${intensityClass} ${className}`}
      aria-hidden="true"
    >
      {/* Magical glow orbs */}
      <div className={styles.glowOrbs}>
        <div className={`${styles.glowOrb} ${styles.orb1}`}></div>
        <div className={`${styles.glowOrb} ${styles.orb2}`}></div>
        <div className={`${styles.glowOrb} ${styles.orb3}`}></div>
      </div>

      {/* Floating particles */}
      <div className={styles.particlesLayer}>
        {particles.map(particle => (
          <div
            key={particle.id}
            className={styles.particle}
            style={{
              left: `${particle.x}%`,
              top: `${particle.y}%`,
              width: `${particle.size}px`,
              height: `${particle.size}px`,
              opacity: particle.opacity,
              animationDelay: `${particle.delay}s`,
              '--particle-hue': particle.hue
            }}
          />
        ))}
      </div>

      {/* Sparkles */}
      <div className={styles.sparklesLayer}>
        {sparkles.map(sparkle => (
          <div
            key={sparkle.id}
            className={styles.sparkle}
            style={{
              left: `${sparkle.x}%`,
              top: `${sparkle.y}%`,
              width: `${sparkle.size}px`,
              height: `${sparkle.size}px`,
              opacity: sparkle.opacity,
              animationDelay: `${sparkle.delay}s`,
              '--sparkle-duration': `${sparkle.duration}s`
            }}
          />
        ))}
      </div>

      {/* Wand trail effect on mouse move */}
      <div className={styles.wandTrailLayer}>
        <div className={styles.wandTrail}></div>
      </div>

      {children && (
        <div className={styles.content} style={{ position: 'relative', zIndex: 1 }}>
          {children}
        </div>
      )}
    </div>
  )
}

export default MagicBackground","path":"/kaggle/working/Website/src/components/MagicBackground/MagicBackground.jsx"}

{"content":".container {
  position: fixed;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
  background: 
    radial-gradient(ellipse 80% 50% at 20% 20%, rgba(255, 215, 0, 0.03) 0%, transparent 50%),
    radial-gradient(ellipse 60% 40% at 80% 80%, rgba(155, 89, 182, 0.03) 0%, transparent 50%),
    radial-gradient(ellipse 50% 30% at 50% 50%, rgba(255, 215, 0, 0.02) 0%, transparent 60%);
}

/* Intensity variants */
.low {
  opacity: 0.5;
}

.medium {
  opacity: 1;
}

.high {
  opacity: 1.5;
}

/* Glow orbs - large ambient magical glows */
.glowOrbs {
  position: absolute;
  inset: 0;
}

.glowOrb {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  animation: orbFloat 20s ease-in-out infinite;
}

.orb1 {
  width: 400px;
  height: 400px;
  top: -100px;
  left: -100px;
  background: radial-gradient(circle, rgba(255, 215, 0, 0.15) 0%, transparent 70%);
  animation-delay: 0s;
}

.orb2 {
  width: 300px;
  height: 300px;
  bottom: -50px;
  right: -50px;
  background: radial-gradient(circle, rgba(155, 89, 182, 0.12) 0%, transparent 70%);
  animation-delay: -7s;
}

.orb3 {
  width: 250px;
  height: 250px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, rgba(255, 193, 7, 0.1) 0%, transparent 70%);
  animation-delay: -14s;
}

@keyframes orbFloat {
  0%, 100% { transform: translate(0, 0) scale(1); }
  25% { transform: translate(30px, -20px) scale(1.1); }
  50% { transform: translate(-20px, 30px) scale(0.95); }
  75% { transform: translate(-30px, -10px) scale(1.05); }
}

/* Particles layer */
.particlesLayer {
  position: absolute;
  inset: 0;
}

.particle {
  position: absolute;
  border-radius: 50%;
  background: hsl(var(--particle-hue), 100%, 60%);
  box-shadow: 
    0 0 4px hsl(var(--particle-hue), 100%, 60%),
    0 0 8px hsl(var(--particle-hue), 100%, 40%);
  animation: particleRise 15s linear infinite;
  will-change: transform, opacity;
}

@keyframes particleRise {
  0% {
    transform: translateY(0) translateX(0) scale(1);
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  90% {
    opacity: 1;
  }
  100% {
    transform: translateY(-120vh) translateX(var(--tx, 0)) scale(0);
    opacity: 0;
  }
}

/* Sparkles layer */
.sparklesLayer {
  position: absolute;
  inset: 0;
}

.sparkle {
  position: absolute;
  background: var(--color-gold-gradient);
  clip-path: polygon(
    50% 0%, 61% 35%, 98% 35%, 68% 57%,
    79% 91%, 50% 70%, 21% 91%, 32% 57%,
    2% 35%, 39% 35%
  );
  animation: sparkleTwinkle var(--sparkle-duration) ease-in-out infinite;
  will-change: transform, opacity;
}

@keyframes sparkleTwinkle {
  0%, 100% {
    transform: scale(0) rotate(0deg);
    opacity: 0;
  }
  20% {
    transform: scale(1) rotate(45deg);
    opacity: 1;
  }
  50% {
    transform: scale(1.2) rotate(90deg);
    opacity: 0.8;
  }
  80% {
    transform: scale(1) rotate(135deg);
    opacity: 1;
  }
}

/* Wand trail layer */
.wandTrailLayer {
  position: absolute;
  inset: 0;
}

.wandTrail {
  position: fixed;
  width: 20px;
  height: 20px;
  pointer-events: none;
  border-radius: 50%;
  background: var(--color-gold-gradient);
  filter: blur(8px);
  opacity: 0;
  transform: translate(-50%, -50%);
  transition: opacity 0.1s ease, transform 0.05s ease;
  z-index: 9999;
}

.wandTrail.active {
  opacity: 0.8;
}

/* Content wrapper */
.content {
  position: relative;
  z-index: 1;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .container {
    animation: none !important;
  }

  .glowOrb,
  .particle,
  .sparkle {
    animation: none !important;
    opacity: 0.1 !important;
  }

  .wandTrail {
    display: none !important;
  }
}","path":"/kaggle/working/Website/src/components/MagicBackground/MagicBackground.module.css"}

