  7→/**
  8→ * Hook for detecting scroll position and direction
  9→ */
 10→export const useScroll = () => {
 11→  const [scrollY, setScrollY] = useState(0)
 12→  const [scrollDirection, setScrollDirection] = useState('up')
 13→  const lastScrollY = useRef(0)
 14→
 15→  useEffect(() => {
 16→    const handleScroll = () => {
 17→      const currentScrollY = window.scrollY
 18→      setScrollDirection(currentScrollY > lastScrollY.current ? 'down' : 'up')
 19→      setScrollY(currentScrollY)
 20→      lastScrollY.current = currentScrollY
 21→    }
 22→
 23→    window.addEventListener('scroll', handleScroll, { passive: true })
 24→    return () => window.removeEventListener('scroll', handleScroll)
 25→  }, [])
 26→
 27→  return { scrollY, scrollDirection }
 28→}
