 33→export const useScrollSpy = (sectionIds, options = {}) => {
 34→  const [activeSection, setActiveSection] = useState(null)
 35→  const observerRef = useRef(null)
 36→
 37→  const { offset = 100, rootMargin = '-20% 0px -60% 0px' } = options
 38→
 39→  useEffect(() => {
