 44→            setActiveSection(entry.target.id)
 45→          }
 46→        })
 47→      },
 48→      { rootMargin, threshold: 0 }
 49→    )
 50→
 51→    observerRef.current = observer
 52→    sectionIds.forEach(id => {
 53→      const element = document.getElementById(id)
 54→      if (element) observer.observe(element)
 55→    })
 56→
 57→    return () => {
