257→export const useForm = (initialValues = {}) => {
258→  const [values, setValues] = useState(initialValues)
259→  const [errors, setErrors] = useState({})
260→  const [touched, setTouched] = useState({})
261→
262→  const handleChange = (e) => {
263→    const { name, value, type, checked } = e.target
264→    setValues(prev => ({
265→      ...prev,
266→      [name]: type === 'checkbox' ? checked : value
267→    }))
268→  }
269→
270→  const handleBlur = (e) => {
271→    const { name } = e.target
272→    setTouched(prev => ({ ...prev, [name]: true }))
273→  }
274→
275→  const setFieldError = (name, error) => {
276→    setErrors(prev => ({ ...prev, [name]: error }))
277→  }
278→
279→  const validate = (validationRules) => {
280→    const newErrors = {}
281→    Object.keys(validationRules).forEach(field => {
282→      const rule = validationRules[field]
283→      const value = values[field]
284→      if (rule.required && !value) {
285→        newErrors[field] = rule.message || `${field} is required`
286→      } else if (rule.pattern && !rule.pattern.test(value)) {
287→        newErrors[field] = rule.message || `${field} is invalid`
288→      } else if (rule.custom && !rule.custom(value)) {
289→        newErrors[field] = rule.message || `${field} is invalid`
290→      }
291→    })
292→    setErrors(newErrors)
293→    return Object.keys(newErrors).length === 0
294→  }
295→
296→  const reset = () => {
297→    setValues(initialValues)
298→    setErrors({})
299→    setTouched({})
300→  }
301→
302→  return {
303→    values,
304→    errors,
305→    touched,
306→    handleChange,
307→    handleBlur,
308→    setFieldError,
309→    validate,
310→    reset,
311→    setValues
312→  }
