348→    const handleResize = () => {
349→      setSize({
350→        width: window.innerWidth,
351→        height: window.innerHeight
352→      })
353→    }
354→
355→    window.addEventListener('resize', handleResize)
356→    return () => window.removeEventListener('resize', handleResize)
357→  }, [])
