362→/**
363→ * Hook for click outside detection
364→ */
365→export const useClickOutside = (callback) => {
366→  const ref = useRef(null)
367→
368→  useEffect(() => {
369→    const handleClick = (e) => {
370→      if (ref.current && !ref.current.contains(e.target)) {
371→        callback()
372→      }
373→    }
374→
375→    document.addEventListener('mousedown', handleClick)
376→    return () => document.removeEventListener('mousedown', handleClick)
377→  }, [callback])
378→
379→  return ref
380→}
