382→/**
383→ * Hook for managing async state
384→ */
385→export const useAsync = (asyncFunction, dependencies = []) => {
386→  const [data, setData] = useState(null)
387→  const [loading, setLoading] = useState(true)
388→  const [error, setError] = useState(null)
389→
390→  useEffect(() => {
391→    let mounted = true
392→
393→    const execute = async () => {
394→      setLoading(true)
395→      setError(null)
396→      try {
397→        const result = await asyncFunction()
398→        if (mounted) {
399→          setData(result)
400→        }
401→      } catch (err) {
402→        if (mounted) {
403→          setError(err)
404→        }
405→      } finally {
406→        if (mounted) {
407→          setLoading(false)
408→        }
409→      }
410→    }
411→
412→    execute()
413→    return () => { mounted = false }
414→  }, dependencies)
415→
416→  return { data, loading, error }
417→}
418→
419→/**
420→ * Hook for copying to clipboard
421→ */
422→export const useClipboard = () => {
423→  const [copied, setCopied] = useState(false)
424→
425→  const copy = useCallback(async (text) => {
426→    try {
427→      await navigator.clipboard.writeText(text)
428→      setCopied(true)
429→      setTimeout(() => setCopied(false), 2000)
430→      return true
431→    } catch {
432→      setCopied(false)
433→      return false
434→    }
435→  }, [])
436→
437→  return { copy, copied }
438→}

