{"content":"import { useEffect, useRef, useState } from 'react'
import { useWandCursor, useReducedMotion } from '../../hooks'
import styles from './WandCursor.module.css'

export const WandCursor = () => {
  const reducedMotion = useReducedMotion()
  const { mousePosition, isMoving, trail } = useWandCursor(!reducedMotion)
  const [showCursor, setShowCursor] = useState(true)
  const cursorRef = useRef(null)
  const trailContainerRef = useRef(null)

  useEffect(() => {
    if (reducedMotion) return

    const handleMouseEnter = () => setShowCursor(true)
    const handleMouseLeave = () => setShowCursor(false)

    window.addEventListener('mouseenter', handleMouseEnter)
    window.addEventListener('mouseleave', handleMouseLeave)

    return () => {
      window.removeEventListener('mouseenter', handleMouseEnter)
      window.removeEventListener('mouseleave', handleMouseLeave)
    }
  }, [reducedMotion])

  if (reducedMotion || !showCursor) return null

  return (
    <>
      {/* Main cursor */}
      <div
        ref={cursorRef}
        className={styles.cursor}
        style={{
          left: `${mousePosition.x}px`,
          top: `${mousePosition.y}px`,
          opacity: isMoving ? 1 : 0.5
        }}
        aria-hidden="true"
      >
        <div className={styles.cursorCore}></div>
        <div className={styles.cursorGlow}></div>
        <div className={styles.cursorSparkle}></div>
      </div>

      {/* Trail particles */}
      <div ref={trailContainerRef} className={styles.trailContainer} aria-hidden="true">
        {trail.map((point, index) => (
          <div
            key={index}
            className={styles.trailParticle}
            style={{
              left: `${point.x}px`,
              top: `${point.y}px`,
              width: `${point.size}px`,
              height: `${point.size}px`,
              opacity: Math.max(0, 1 - (Date.now() - point.time) / 500),
              animationDelay: `${index * 10}ms`
            }}
          />
        ))}
      </div>

      {/* Click burst effect */}
      <ClickBurst />
    </>
  )
}

/* Click burst component */
const ClickBurst = () => {
  const [bursts, setBursts] = useState([])
  const reducedMotion = useReducedMotion()

  useEffect(() => {
    if (reducedMotion) return

    const handleClick = (e) => {
      const burstId = Date.now()
      const particleCount = 12
      const newBurst = {
        id: burstId,
        x: e.clientX,
        y: e.clientY,
        particles: Array.from({ length: particleCount }, (_, i) => ({
          id: i,
          angle: (i / particleCount) * Math.PI * 2,
          distance: 0,
          maxDistance: 30 + Math.random() * 50,
          size: 4 + Math.random() * 6,
          color: `hsl(${45 + Math.random() * 30}, 100%, 60%)`,
          delay: Math.random() * 100
        }))
      }

      setBursts(prev => [...prev, newBurst])

      // Remove burst after animation
      setTimeout(() => {
        setBursts(prev => prev.filter(b => b.id !== burstId))
      }, 1000)
    }

    window.addEventListener('click', handleClick)
    return () => window.removeEventListener('click', handleClick)
  }, [reducedMotion])

  return (
    <div className={styles.burstContainer} aria-hidden="true">
      {bursts.map(burst => (
        <div key={burst.id} className={styles.burst} style={{ left: `${burst.x}px`, top: `${burst.y}px` }}>
          {burst.particles.map(p => (
            <div
              key={p.id}
              className={styles.burstParticle}
              style={{
                '--angle': `${p.angle}rad`,
                '--distance': `${p.maxDistance}px`,
                '--size': `${p.size}px`,
                '--color': p.color,
                '--delay': `${p.delay}ms`
              }}
            />
          ))}
        </div>
      ))}
    </div>
  )
}

export default WandCursor","path":"/kaggle/working/Website/src/components/WandCursor/WandCursor.jsx"}

{"content":"/* Main cursor */
.cursor {
  position: fixed;
  pointer-events: none;
  z-index: 9999;
  transform: translate(-50%, -50%);
  transition: opacity 0.1s ease, transform 0.05s ease;
  will-change: transform, opacity;
}

.cursorCore {
  width: 16px;
  height: 16px;
  background: var(--color-gold-gradient);
  border-radius: 50%;
  box-shadow: 
    0 0 8px var(--color-gold-primary),
    0 0 16px var(--color-gold-primary),
    inset 0 0 8px rgba(255, 255, 255, 0.3);
  animation: cursorPulse 2s ease-in-out infinite;
}

.cursorGlow {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 32px;
  height: 32px;
  background: radial-gradient(circle, rgba(255, 215, 0, 0.4) 0%, transparent 70%);
  border-radius: 50%;
  animation: cursorGlowPulse 1.5s ease-in-out infinite;
}

.cursorSparkle {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 8px;
  height: 8px;
  background: var(--color-gold-gradient);
  clip-path: polygon(
    50% 0%, 61% 35%, 98% 35%, 68% 57%,
    79% 91%, 50% 70%, 21% 91%, 32% 57%,
    2% 35%, 39% 35%
  );
  animation: cursorSparkleSpin 3s linear infinite;
}

@keyframes cursorPulse {
  0%, 100% { transform: scale(1); box-shadow: 0 0 8px var(--color-gold-primary), 0 0 16px var(--color-gold-primary); }
  50% { transform: scale(1.2); box-shadow: 0 0 16px var(--color-gold-primary), 0 0 32px var(--color-gold-primary); }
}

@keyframes cursorGlowPulse {
  0%, 100% { transform: translate(-50%, -50%) scale(1); opacity: 0.4; }
  50% { transform: translate(-50%, -50%) scale(1.5); opacity: 0.8; }
}

@keyframes cursorSparkleSpin {
  from { transform: translate(-50%, -50%) rotate(0deg) scale(1); }
  to { transform: translate(-50%, -50%) rotate(360deg) scale(1); }
}

/* Trail particles */
.trailContainer {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9998;
}

.trailParticle {
  position: absolute;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: var(--color-gold-gradient);
  box-shadow: 0 0 6px var(--color-gold-primary);
  animation: trailFade 0.5s ease-out forwards;
  will-change: transform, opacity;
}

@keyframes trailFade {
  from {
    transform: translate(-50%, -50%) scale(1);
    opacity: 0.8;
  }
  to {
    transform: translate(-50%, -50%) scale(0);
    opacity: 0;
  }
}

/* Click burst */
.burstContainer {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9997;
}

.burst {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 0;
  height: 0;
}

.burstParticle {
  position: absolute;
  top: 0;
  left: 0;
  width: var(--size);
  height: var(--size);
  background: var(--color);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--color);
  animation: burstExpand 0.8s ease-out forwards;
  animation-delay: var(--delay);
  will-change: transform, opacity;
}

@keyframes burstExpand {
  0% {
    transform: translate(-50%, -50%) rotate(var(--angle)) translateX(0) scale(1);
    opacity: 1;
  }
  100% {
    transform: translate(-50%, -50%) rotate(var(--angle)) translateX(var(--distance)) scale(0);
    opacity: 0;
  }
}

/* Hover effects for interactive elements */
.hoverMagical {
  position: relative;
}

.hoverMagical::before {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: inherit;
  background: var(--color-gold-gradient);
  opacity: 0;
  transition: opacity var(--transition-normal);
  z-index: -1;
  filter: blur(8px);
}

.hoverMagical:hover::before {
  opacity: 0.6;
  animation: borderGlow 2s ease-in-out infinite;
}

@keyframes borderGlow {
  0%, 100% { opacity: 0.4; filter: blur(8px); }
  50% { opacity: 0.8; filter: blur(12px); }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .cursor,
  .cursorCore,
  .cursorGlow,
  .cursorSparkle,
  .trailParticle,
  .burstParticle {
    animation: none !important;
    transition: none !important;
  }

  .cursor {
    opacity: 0.5 !important;
  }

  .trailContainer,
  .burstContainer {
    display: none !important;
  }
}","path":"/kaggle/working/Website/src/components/WandCursor/WandCursor.module.css"}

